    return words[0].lower() + "".join(word.capitalize() for word in words[1:])

import re

def a_snake(s):
    # Reemplaza mayúsculas seguidas de minúsculas con un guion bajo y la letra en minúscula
    s = re.sub(r'(?<!^)(?=[A-Z])', '_', s)
    # Convierte todo a minúsculas
    return s.lower()

def primos(n):
    if n < 2:
        return []
    es_primo = [True] * (n + 1)
    es_primo[0] = es_primo[1] = False
    p = 2
    while (p * p <= n):
        if es_primo[p]:
            for i in range(p * p, n + 1, p):
                es_primo[i] = False
        p += 1
    lista_primos = []
    for p in range(2, n + 1):
        if es_primo[p]:
            lista_primos.append(p)
    return lista_primos

def mcd(a, b):
    # Algoritmo de Euclides
    while b:
        a, b = b, a % b
    return a

def comprimir(s):
    if not s:
        return s

    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    compressed_parts = []
    i = 0
    while i < len(s):
        char = s[i]
        count = 0
        j = i
        while j < len(s) and s[j] == char:
            count += 1
            j += 1
        compressed_parts.append(char + str(count))
        i = j

    compressed = "".join(compressed_parts)

    return compressed if len(compressed) < len(s) else s

def balanceado(s):
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}
    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False
    return not stack

def transpuesta(m):
    if not m:
        return []
    num_filas = len(m)
    num_columnas = len(m[0])
    transpuesta_m = [[0] * num_filas for _ in range(num_columnas)]
    for i in range(num_filas):
        for j in range(num_columnas):
            transpuesta_m[j][i] = m[i][j]
    return transpuesta_m

