def formatear_bytes(n):
    if n == 0:
        return "0 B"
    unidades = ["B", "KB", "MB", "GB"]
    i = 0
    while n >= 1024 and i < len(unidades) - 1:
        n /= 1024.0
        i += 1
    if i == 0:
        return f"{int(n)} B"
    else:
        return f"{n:.1f} {unidades[i]}"

