        return []
    return [lista[i:i + n] for i in range(0, len(lista), n)]

def dedup(lista):
    seen = set()
    resultado = []
    for item in lista:
        if item not in seen:
            seen.add(item)
            resultado.append(item)
    return resultado

def anidar(plano):
    # Inicializa el diccionario de salida
    resultado = {}
    # Itera sobre los pares clave-valor del diccionario de entrada
    for clave, valor in plano.items():
        # Divide la clave por puntos
        partes = clave.split('.')
        # Navega y construye la estructura anidada
        actual = resultado
        for i, parte in enumerate(partes):
            if i == len(partes) - 1:
                # Si es la última parte, asigna el valor
                actual[parte] = valor
            else:
                # Si no es la última parte, asegura que la clave sea un diccionario
                if parte not in actual or not isinstance(actual[parte], dict):
                    actual[parte] = {}
                # Avanza al siguiente nivel
                actual = actual[parte]
    return resultado

def promedio_movil(nums, ventana):
    if len(nums) < ventana:
        return []

    promedios = []
    for i in range(len(nums) - ventana + 1):
        promedio = sum(nums[i:i+ventana]) / ventana
        promedios.append(promedio)
    return promedios

