def parsear_query(s):
    if not s:
        return {}
    query_dict = {}
    pairs = s.split('&')
    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
            query_dict[key] = value
        elif pair:
            query_dict[pair] = ""
    return query_dict

def contar_islas(grid):
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    count = 0

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or visited[r][c] or grid[r][c] == 0:
            return
        visited[r][c] = True
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                count += 1
                dfs(r, c)
    return count

def distancia(a, b):
    # Inicializar la matriz de distancias
    m = len(a)
    n = len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Llenar la primera fila y columna
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Llenar la matriz
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,        # Borrar
                dp[i][j - 1] + 1,        # Insertar
                dp[i - 1][j - 1] + cost  # Sustituir/Igual
            )

    return dp[m][n]

def validar_password(p):
    # Verificar longitud
    if len(p) < 8:
        return False
    # Verificar mayúscula
    if not any(c.isupper() for c in p):
        return False
    # Verificar minúscula
    if not any(c.islower() for c in p):
        return False
    # Verificar dígito
    if not any(c.isdigit() for c in p):
        return False
    # Verificar no alfanumérico
    if not any(not c.isalnum() for c in p):
        return False
    return True

def campo_csv(s):
    # Verificar si el campo requiere ser encerrado en comillas
    if ',' in s or '"' in s or '\n' in s:
        # Escapar comillas dobles duplicándolas
        s_escaped = s.replace('"', '""')
        # Devolver entre comillas dobles
        return f'"{s_escaped}"'
    else:
        # Devolver tal cual si no contiene caracteres especiales
        return s

def titular(s):
    palabras = s.lower().split()
    resultado = []
    for i, palabra in enumerate(palabras):
        if i == 0:
            resultado.append(palabra.capitalize())
        else:
            if palabra in ['de', 'del', 'la', 'las', 'el', 'los', 'y']:
                resultado.append(palabra)
